create or replace function public.ca_v2_public_weekend(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$declare hashed text;minute_bucket timestamptz=date_trunc('minute',now());observed_hits integer;result jsonb;begin if length(p_token)<>64 or p_token !~ '^[a-f0-9]+$' then raise exception 'Link unavailable';end if;hashed=encode(extensions.digest(p_token,'sha256'),'hex');select snapshot into result from ca_private.weekend_publications where token_hash=hashed;if result is null then return null;end if;delete from ca_private.v2_public_limits where token_hash=hashed and bucket<minute_bucket-interval '2 minutes';insert into ca_private.v2_public_limits(token_hash,bucket,hits) values(hashed,minute_bucket,1) on conflict(token_hash,bucket) do update set hits=v2_public_limits.hits+1 returning v2_public_limits.hits into observed_hits;if observed_hits>60 then raise exception 'Too many requests. Try again shortly.';end if;return result;end $$;
